<script lang="ts">
 import {onDestroy,tick} from 'svelte';
 import {beforeNavigate} from '$app/navigation';
 import type {Account} from '../domain/account';
 import {apiTokenStatus,type ApiToken,type ApiTokensGateway} from '../application/api-tokens';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import SectionHeading from '$lib/shared/presentation/ui/SectionHeading.svelte';
 let {user,gateway}:{user:Account|null;gateway:ApiTokensGateway}=$props();
 const {locale}=useLocale();
 let items=$state<ApiToken[]>([]),name=$state(''),days=$state(30),direct=$state(false),busy=$state(false),loaded=$state(false),failed=$state(false),uncertain=$state(false),secret=$state(''),copied=$state(false),copyFailed=$state(false),selected=$state<ApiToken|null>(null),dialog=$state<HTMLDialogElement>(),secretPanel=$state<HTMLElement>();
 let generation=0;
 const allowed=$derived(user?.role==='admin'&&user.verified);
 function clear(){generation++;name='';days=30;direct=false;secret='';copied=false;copyFailed=false;items=[];selected=null;dialog?.close();busy=false;loaded=false;failed=false;uncertain=false;}
 $effect(()=>{const account=user?.id,permitted=allowed;clear();if(account&&permitted)void load(account,generation);});
 beforeNavigate(()=>clear());
 onDestroy(clear);
 function current(account:string,version:number){return user?.id===account&&allowed&&version===generation;}
 async function load(account=user?.id,version=generation){if(!account)return;busy=true;failed=false;try{const result=await gateway.list(account);if(current(account,version)){items=result;loaded=true;}}catch{if(current(account,version))failed=true;}finally{if(current(account,version))busy=false;}}
 async function create(){if(!user||busy||secret||uncertain)return;const account=user.id,version=generation;busy=true;failed=false;try{const result=await gateway.create(account,{name:name.trim(),expiresInDays:days,directPublish:direct});if(current(account,version)){secret=result.token;items=[result.item,...items];name='';await tick();if(current(account,version))secretPanel?.focus();}}catch{if(current(account,version)){failed=true;uncertain=true;loaded=false;}}finally{if(current(account,version))busy=false;}}
 async function copy(){const value=secret,version=generation;try{await navigator.clipboard.writeText(value);if(version===generation&&secret===value){copied=true;copyFailed=false;}}catch{if(version===generation)copyFailed=true;}}
 async function choose(item:ApiToken){const version=generation;selected=item;await tick();if(version===generation&&selected?.id===item.id)dialog?.showModal();}
 async function revoke(){if(!user||!selected||busy)return;const account=user.id,version=generation,id=selected.id;busy=true;failed=false;try{await gateway.revoke(account,id);if(current(account,version)){selected=null;dialog?.close();await load(account,version);}}catch{if(current(account,version))failed=true;}finally{if(current(account,version))busy=false;}}
 function date(value:string){return new Date(value).toLocaleString($locale==='kk'?'kk-KZ':'ru-RU');}
 function status(item:ApiToken){const value=apiTokenStatus(item);return value==='revoked'?text($locale,'Қайтарылған','Отозван'):value==='expired'?text($locale,'Мерзімі аяқталған','Истёк'):text($locale,'Белсенді','Активен');}
</script>
<svelte:head><title>{text($locale,'API токендері','API-токены')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
<SectionHeading level={1} title={text($locale,'API токендері','API-токены')} description={text($locale,'Codex арқылы өз аккаунтыңыздан тараулар жүктеу. Токенді құпия сақтаңыз.','Загрузка глав через Codex от своего аккаунта. Храните токен в секрете.')}/>
{#if allowed}
 {#if failed}<p role="alert">{text($locale,'Сұрау орындалмады.','Запрос не выполнен.')}</p>{/if}
 {#if uncertain}<aside role="status"><p>{text($locale,'Токен жасалған болуы мүмкін. Қайта жасамас бұрын тізімді жаңартып, белгісіз токенді қайтарыңыз.','Токен мог быть создан. Обновите список и отзовите неизвестный токен перед новым созданием.')}</p><button class="button subtle" disabled={busy} onclick={()=>load()}>{text($locale,'Тізімді жаңарту','Обновить список')}</button><button class="button subtle" disabled={busy||!loaded} onclick={()=>{uncertain=false;failed=false;}}>{text($locale,'Тізімді тексердім','Список проверен')}</button></aside>{/if}
 {#if secret}<section class="secret" bind:this={secretPanel} tabindex="-1" aria-label={text($locale,'Жаңа токен','Новый токен')}><h2>{text($locale,'Токен тек бір рет көрсетіледі','Токен показывается только один раз')}</h2><p>{text($locale,'Көшіріп, қауіпсіз жерде сақтаңыз. Жасырғаннан кейін қайта көру мүмкін емес.','Скопируйте и сохраните в безопасном месте. После скрытия посмотреть его снова нельзя.')}</p><code>{secret}</code><div class="actions"><button class="button primary" onclick={copy}>{text($locale,'Көшіру','Копировать')}</button><button class="button subtle" onclick={()=>{secret='';copied=false;copyFailed=false;}}>{text($locale,'Жасыру','Скрыть')}</button></div>{#if copied}<p role="status">{text($locale,'Көшірілді','Скопировано')}</p>{/if}{#if copyFailed}<p role="alert">{text($locale,'Көшіру мүмкін болмады. Токенді қолмен таңдаңыз.','Не удалось скопировать. Выделите токен вручную.')}</p>{/if}</section>{/if}
 <form onsubmit={event=>{event.preventDefault();void create();}}><label>{text($locale,'Токен атауы','Название токена')}<input bind:value={name} required maxlength="100" disabled={busy||!!secret||uncertain}/></label><label>{text($locale,'Жарамдылық мерзімі, күн','Срок действия, дней')}<input type="number" min="1" max="365" step="1" bind:value={days} required disabled={busy||!!secret||uncertain}/></label><label class="check"><input type="checkbox" bind:checked={direct} disabled={busy||!!secret||uncertain}/>{text($locale,'Модерациясыз жариялау','Публиковать без модерации')}</label><p class="muted">{text($locale,'Токен тек өз аккаунтыңызға тиесілі. Модерациясыз жариялау жүктелген нұсқаны бірден жариялауға рұқсат береді.','Токен принадлежит только вашему аккаунту. Публикация без модерации разрешает сразу публиковать загруженную версию.')}</p><button class="button primary" disabled={busy||!!secret||uncertain}>{text($locale,'Токен жасау','Создать токен')}</button></form>
 <section class="tokens" aria-label={text($locale,'Менің токендерім','Мои токены')} aria-busy={busy}>{#each items as item (item.id)}<article><div><strong>{item.name}</strong><small>{item.prefix}… · {status(item)}</small><small>{text($locale,'Жасалды','Создан')}: {date(item.createdAt)}</small><small>{text($locale,'Мерзімі','Действует до')}: {date(item.expiresAt)}</small><small>{text($locale,'Соңғы қолданылуы','Последнее использование')}: {item.lastUsedAt?date(item.lastUsedAt):text($locale,'Қолданылмаған','Не использовался')}</small><small>{item.directPublish?text($locale,'Модерациясыз жариялау','Публикация без модерации'):text($locale,'Модерациямен','С модерацией')}</small></div>{#if !item.revokedAt}<button class="button subtle" disabled={busy} onclick={()=>choose(item)}>{text($locale,'Қайтару','Отозвать')}</button>{/if}</article>{:else}<p>{busy?text($locale,'Жүктелуде…','Загрузка…'):loaded?text($locale,'Токендер жоқ','Токенов нет'):text($locale,'Тізім жүктелмеді','Список не загружен')}</p>{/each}</section>
 {#if failed&&!uncertain}<button class="button subtle" disabled={busy} onclick={()=>load()}>{text($locale,'Тізімді жаңарту','Обновить список')}</button>{/if}
 <p class="muted">{text($locale,'CLI үшін токенді QMANGA_API_TOKEN орта айнымалысына қауіпсіз орнатыңыз. Токенді URL-ға немесе журналға жазбаңыз.','Для CLI безопасно задайте токен в переменной окружения QMANGA_API_TOKEN. Не записывайте токен в URL или журналы.')}</p>
 <dialog bind:this={dialog} oncancel={event=>{if(busy)event.preventDefault();else selected=null;}} aria-labelledby="revoke-title"><h2 id="revoke-title">{text($locale,'Токенді қайтару керек пе?','Отозвать токен?')}</h2><p>{selected?.name}</p><p>{text($locale,'Бұл токенмен жаңа сұраулар бірден тоқтайды.','Новые запросы с этим токеном сразу перестанут работать.')}</p><div class="actions"><button class="button subtle" disabled={busy} onclick={()=>{selected=null;dialog?.close();}}>{text($locale,'Бас тарту','Отмена')}</button><button class="button primary" disabled={busy} onclick={revoke}>{text($locale,'Қайтару','Отозвать')}</button></div>{#if failed}<p role="alert">{text($locale,'Қайтару орындалмады. Қайта көріңіз.','Не удалось отозвать. Повторите попытку.')}</p>{/if}</dialog>
{:else}<p>{text($locale,'Расталған әкімші аккаунты қажет.','Нужен подтверждённый аккаунт администратора.')}</p>{/if}
<style>
 form{display:grid;gap:16px;max-width:640px;margin:24px 0}label{display:grid;gap:8px;font-size:14px}input{min-width:0;min-height:44px}.check{display:flex;align-items:center;min-height:44px}.check input{width:20px;height:20px;min-height:20px;flex-shrink:0}form>button{justify-self:start}.muted,small{color:var(--muted);font-size:13px}.tokens{border:1px solid var(--line);border-radius:12px;overflow:hidden}.tokens article{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px;border-bottom:1px solid var(--line)}article:last-child{border:0}article>div{min-width:0}strong,small{display:block;overflow-wrap:anywhere}small{margin-top:6px}.tokens>p{padding:16px}.secret,aside{padding:20px;background:var(--panel);border:1px solid var(--line);border-radius:12px;margin:20px 0}.secret h2,dialog h2{font-size:20px}.secret code{display:block;overflow-wrap:anywhere;user-select:all;padding:16px 0}.actions{display:flex;gap:8px;flex-wrap:wrap}.button{min-height:44px}dialog{max-width:480px;width:calc(100% - 32px);padding:24px;color:var(--text);background:var(--panel);border:1px solid var(--line);border-radius:12px}dialog::backdrop{background:#0009}@media(max-width:420px){.tokens article{align-items:start;flex-direction:column}.tokens article button{align-self:flex-end}}
</style>
